def solution(input_str):
    n, m, matrix = parse_input(input_str)

    def is_palindrome_reorderable(s):
        from collections import Counter
        cnt = Counter(s)
        odd_count = sum(1 for x in cnt.values() if x % 2 == 1)
        return odd_count <= 1

    def get_char_signatures_for_row(submatrix_rows, row_idx, col_start, col_end):
        """
        Returns the center character and parity masks for columns.
        For rows that can form palindromes, the center character (if any) 
        must be placed in a column that can form a palindrome at the center.
        """
        results = []
        for i in range(len(submatrix_rows)):
            row_str = ''.join(matrix[submatrix_rows[i] + j][col_start:col_end] for j in range(col_end - col_start))
            cnt = Counter(row_str)
            odd_chars = []
            for c, freq in cnt.items():
                if freq % 2 == 1:
                    odd_chars.append(c)
            if len(odd_chars) == 0:
                center = ''
                mask = 0
            elif len(odd_chars) == 1:
                center = odd_chars[0]
                mask = 1
            else:
                return None  # Cannot form palindrome
            results.append((center, mask))
        return results

    def check_columns(pages, odd_masks, odd_chars_count):
        """
        Check if we can place all center characters into columns that form palindromes.
        Pages represents which rows in the submatrix have odd characters in each column.
        """
        n_cols = len(pages[0])
        col_parity = [0] * n_cols  # Number of odd chars in each column
        can_satisfy = True

        for i in range(len(pages)):
            centers, masks = pages[i][0], pages[i][1]
            for c, mask in enumerate(masks):
                if mask:
                    col_parity[c] += 1

        for col_p in col_parity:
            if col_p % 2 == 1:
                return False
        return True

    count = 0
    for i in range(n):
        for j in range(m):
            for a in range(i + 1):
                for b in range(j + 1):
                    if i == 0 and j == 0:
                        count += 1
                    elif is_palindrome_reorderable(matrix[a+b][b]):
                        count += 1
    return f"{count}\n"
