def hack_solution():
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])
    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by strength descending
    strengths.sort(reverse=True)

    # Track which heroes are picked/banned
    used = [False] * n

    team1_score = 0
    team2_score = 0

    for action, team in actions:
        if action == 'p':
            # Pick - get the strongest available hero
            picked = None
            for i in range(n):
                if not used[i]:
                    picked = i
                    break
            used[picked] = True
            if team == 1:
                team1_score += strengths[picked]
            else:
                team2_score += strengths[picked]
        else:  # action == 'b'
            # Ban - ban the strongest available hero
            banned = None
            for i in range(n):
                if not used[i]:
                    banned = i
                    break
            used[banned] = True

    return f"{team1_score - team2_score}\n"

