    for i in range(1, n + 1):
        ai, bi = map(int, lines[i].split())
        p[i] = (ai, bi)
    p_values = [p[i][0] / p[i][1] for i in range(n + 1)]

    tree = [1.0] * (2 * (n + 1))

    def build(idx, l, r):
        if l == r:
            tree[idx] = p_values[l]
        else:
            mid = (l + r) // 2
            build(2 * idx, l, mid)
            build(2 * idx + 1, mid + 1, r)
            tree[idx] = tree[2 * idx] * tree[2 * idx + 1]
    build(1, 1, n)

    def update(pos, new_val):
        tree[pos + n] = new_val
        pos += n
        while pos > 1:
            tree[pos >> 1] = tree[pos] * tree[pos ^ 1]
            pos >>= 1

    def query(l, r):
        res = 1.0
        l += n
        r += n
        while l <= r:
            if l % 2 == 1:
                res *= tree[l]
                l += 1
            if r % 2 == 0:
                res *= tree[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    results = []
    for i in range(n + 1, n + 1 + q):
        parts = lines[i].split()
        if parts[0] == '1':
            idx, a, b = int(parts[1]), int(parts[2]), int(parts[3])
            prob = a / b
            update(idx - 1, prob)
            p_values[idx - 1] = prob
        else:
            l, r = int(parts[1]), int(parts[2])
            prob = query(l - 1, r - 1)
            results.append(f"{prob:.10f}")

    return '\n'.join(results)
