def solution(input_str):
    import sys
    sys.setrecursionlimit(10**6)

    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        if i >= 3:
            v, u = map(int, lines[i].split())
            adj[v].append(u)
            adj[u].append(v)

    cycles = []
    used = [False] * (n + 1)

    # Try to find k vertex-disjoint cycles with length not divisible by 3
    iteration = 0
    while len(cycles) < k and iteration < n * n:
        iteration += 1

        for start in range(1, n + 1):
            if used[start]:
                continue

            path = [start]
            stack = [start]
            path_set = {start}
            cycle_found = None

            while stack and cycle_found is None:
                curr = stack[-1]

                progress = False
                for neighbor in adj[curr]:
                    if neighbor == start and len(path) >= 3:
                        cycle_found = path + [neighbor]
                        break
                    elif neighbor not in path_set:
                        path_set.add(neighbor)
                        stack.append(neighbor)
                        path.append(neighbor)
                        progress = True
                        break

                if not progress:
                    path_set.remove(stack.pop())
                    path.pop()

            if cycle_found:
                cycle_len = len(cycle_found) - 1
                if cycle_len % 3 != 0:
                    cycles.append(cycle_found[:-1])
                    for v in cycle_found[:-1]:
                        used[v] = True
                    break

        if len(cycles) < k:
            break

    if len(cycles) == k:
        result = ['CYCLES']
        for cycle in cycles:
            result.append(str(len(cycle)))
            result.append(' '.join(map(str, cycle)))
        return '\n'.join(result)

    # Try to find a long path with at least n/k vertices
    # Use iterative DFS to avoid recursion limit issues
    visited = [False] * (n + 1)
    found_path = False
    final_path = []

    for start in range(1, n + 1):
        if visited[start]:
            continue

        stack = [(start, [start])]
        visited[start] = True

        while stack and not found_path:
            node, path = stack.pop()

            if len(path) >= n // k:
                final_path = path
                found_path = True
                break

            # Sort neighbors by index to try more systematic search
            neighbors_sorted = sorted(adj[node])
            for neighbor in neighbors_sorted:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append((neighbor, path + [neighbor]))

    if found_path and len(final_path) >= n // k:
        result = ['PATH', str(len(final_path)), ' '.join(map(str, final_path))]
        return '\n'.join(result)

    # Last resort: try any valid path or return -1
    visited = [False] * (n + 1)
    stack = [(1, [1])]
    visited[1] = True

    while stack and not found_path:
        node, path = stack.pop()

        if len(path) >= max(n // k, 3):
            final_path = path
            found_path = True
            break

        neighbors_sorted = sorted(adj[node])
        for neighbor in neighbors_sorted:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append((neighbor, path + [neighbor]))

    if found_path:
        result = ['PATH', str(len(final_path)), ' '.join(map(str, final_path))]
        return '\n'.join(result)

    return '-1'
