        if line_idx >= len(lines):
            break

        n = int(lines[line_idx])
        line_idx += 1

        # Parse tree structure
        node_type = []      # 'leaf' or 'internal'
        values = []         # values for leaves
        left = []           # left child index
        right = []          # right child index

        for i in range(n):
            parts = lines[line_idx].split()
            line_idx += 1
            if parts[0] == '-1':
                node_type.append('internal')
                l, r = int(parts[1]), int(parts[2])
                left.append(l)
                right.append(r)
                values.append(0)  # placeholder for internal node
            else:
                node_type.append('leaf')
                left.append(-1)
                right.append(-1)
                values.append(int(parts[0]))

        # For each internal node, compute the optimal value
        # We need to determine who makes the final move at each internal node

        def count_leaves_in_subtree(u):
            if node_type[u] == 'leaf':
                return 1
            else:
                return count_leaves_in_subtree(left[u]) + count_leaves_in_subtree(right[u])

        # For each internal node, compute g(u) = game value for that subtree
        # The key insight: at the final merge at internal node u,
        # if (leaves in left subtree + leaves in right subtree) is even -> Piegirl minimizes
        # if odd -> Pieguy maximizes
        # BUT this is simplified. We need to consider the actual sequence of moves.
        #
        # Actually, for a subtree with L leaves, L-1 merges happen.
        # The player making the last merge at internal node u depends on parity.
        # 
        # Key insight: for node with L leaves in its subtree:
        # - Number of operations to reduce this subtree = L-1 (excluding final merge of node itself)
        # - The final merge happens when left and right are both reduced to leaves
        #
        # The trick: For an internal node u, g(u) depends on parity of leaf count in u
        # If leaf_count[u] is even: Piegirl makes final merge -> min(g(left[u]), g(right[u]))
        # If leaf_count[u] is odd: Pieguy makes final merge -> max(g(left[u]), g(right[u]))
        # BUT: g(leaf) = value of leaf

        memo = {}

        def game(u):
            if node_type[u] == 'leaf':
                return values[u]

            if u in memo:
                return memo[u]

            l_leaves = count_leaves_in_subtree(left[u])
            r_leaves = count_leaves_in_subtree(right[u])
            total_leaves = l_leaves + r_leaves

            # Who makes the final move at this internal node?
            # If total_leaves is even -> Piegirl (minimizing)
            # If total_leaves is odd -> Pieguy (maximizing)
            # This is because L_total - 1 operations happen, and with L_total even,
            # the final operation is on the even turn (Piegurl's move in 0-indexed system)

            left_val = game(left[u])
            right_val = game(right[u])

            memo[u] = min(left_val, right_val) if total_leaves % 2 == 0 else max(left_val, right_val)
            return memo[u]

        results.append(str(game(0)))

    return '\n'.join(results)

