    n = int(lines[0])
    s = lines[1]

    packmen = [i for i in range(n) if s[i] == 'P']
    asterisks = [i for i in range(n) if s[i] == '*']

    m = len(packmen)
    max_asterisks = 0
    min_time = float('inf')

    for mask in range(1 << m):
        eaten_asterisks = set()
        max_time_mask = 0

        for i in range(m):
            pack_pos = packmen[i]
            if mask & (1 << i):
                # Goes right: covers asterisks with position > pack_pos
                for a in asterisks:
                    if a > pack_pos:
                        eaten_asterisks.add(a)
            else:
                # Goes left: covers asterisks with position < pack_pos
                for a in asterisks:
                    if a < pack_pos:
                        eaten_asterisks.add(a)

        count = len(eaten_asterisks)
        if count > max_asterisks:
            max_asterisks = count
            min_time = float('inf')
        elif count == max_asterisks:
            if min_time == float('inf'):
                min_time = float('inf')
            else:
                pass

        # Calculate actual time for this configuration
        time = 0
        for a in eaten_asterisks:
            min_dist = float('inf')
            for i in range(m):
                pack_pos = packmen[i]
                if (mask & (1 << i)) and a > pack_pos:
                    dist = a - pack_pos
                elif not (mask & (1 << i)) and a < pack_pos:
                    dist = pack_pos - a
                else:
                    continue
                min_dist = min(min_dist, dist)
            time = max(time, min_dist)

