The solution uses Disjoint Set Union (DSU) to efficiently find connected components of wires.

```python
import sys
from io import StringIO


class DSU:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

    def same(self, x, y):
        return self.find(x) == self.find(y)


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        wires = []
        contact_to_wires = {}

        for i in range(n):
            if idx >= len(lines):
                break
            parts = lines[idx].split()
            idx += 1
            x, y = int(parts[0]), int(parts[1])
            wires.append({'x': x, 'y': y, 'id': i + 1})

            if x not in contact_to_wires:
                contact_to_wires[x] = []
            contact_to_wires[x].append(i)

            if y not in contact_to_wires:
                contact_to_wires[y] = []
            contact_to_wires[y].append(i)

        if n <= 1:
            results.append("0")
            continue

        dsu = DSU(n)

        for contact, wire_indices in contact_to_wires.items():
            for i in range(1, len(wire_indices)):
                dsu.union(wire_indices[0], wire_indices[i])

        component_wires = {}
        for i in range(n):
            root = dsu.find(i)
            if root not in component_wires:
                component_wires[root] = []
            component_wires[root].append(i)

        components = list(component_wires.values())
        num_components = len(components)

        if num_components == 1:
            results.append("0")
            continue

        results.append(str(num_components - 1))

        first_comp = components[0]
        first_wire = wires[first_comp[0]]

        for comp in components[1:]:
            wire = wires[comp[0]]

            if wire['x'] != first_wire['x'] and first_wire['x'] != wire['y']:
                new_x = first_wire['x']
            elif wire['y'] != first_wire['y'] and first_wire['y'] != wire['x']:
                new_x = first_wire['y']
            else:
                new_x = first_wire['x']
                if new_x == wire['y']:
                    new_x = first_wire['y']

            if wire['x'] == new_x:
                new_x = first_wire['y']
                if new_x == wire['y']:
                    new_x = first_wire['x']

            if first_wire['x'] != wire['y'] and wire['x'] != first_wire['y']:
                new_x = first_wire['x']

            if wire['x'] != new_x:
                results.append(f"{wire['id']} {wire['x']} {new_x}")

    return "\n".join(results) + "\n"


