def solution(input_str):
    import os

    MOD = 10**9 + 7

    lines = input_str.strip().split('\n')
    q = int(lines[0])

    queries = []
    max_r, max_n = 0, 0
    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))
        max_r = max(max_r, r)
        max_n = max(max_n, n)

    if max_r == 0:
        results = []
        for r, n in queries:
            cnt = 0
            temp = n
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    cnt += 1
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                cnt += 1
            results.append(str((1 << cnt) % MOD))
        return '\n'.join(results)

    INF_N = max_n + 1

    omega = [0] * INF_N
    omega[1] = 0
    is_prime = [True] * INF_N
    primes = []

    for i in range(2, INF_N):
        if is_prime[i]:
            primes.append(i)
            omega[i] = 1
        for p in primes:
            if i * p >= INF_N:
                break
            is_prime[i * p] = False
            if i % p == 0:
                omega[i * p] = omega[i]
            else:
                omega[i * p] = omega[i] + 1

    f0 = [(1 << omega[i]) % MOD for i in range(INF_N)]

    prev = list(f0)

    results = {}

    divs = [[] for _ in range(INF_N)]
    for i in range(1, INF_N):
        for j in range(i, INF_N, i):
            divs[j].append(i)

    for r in range(1, max_r + 1):
        curr = [0] * INF_N
        for n in range(1, INF_N):
            acc = 0
            for d in divs[n]:
                acc += prev[d]
                if acc >= MOD:
                    acc -= MOD
            curr[n] = acc
        prev = curr

        for r_idx, n in queries:
            if r_idx == r:
                results[(r_idx, n)] = prev[n]

    for r, n in queries:
        if r == 0:
            cnt = 0
            temp = n
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    cnt += 1
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                cnt += 1
            results[(r, n)] = (1 << cnt) % MOD
        if (r, n) not in results:
            results[(r, n)] = 0

    return '\n'.join(str(results[(r, n)]) for r, n in queries)
