def solution(input_str):
    """
    Find the k-th two-dimensional correct bracket array of size n×m.
    A correct bracket array is one where all monotonic paths from (1,1) to (n,m)
    form valid bracket sequences.
    """
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    # Parse priority grid
    priorities = []
    idx = 1
    for i in range(n):
        priorities.append(list(map(int, lines[idx].split())))
        idx += 1

    # Quick validation
    if (n * m) % 2 != 0 or k < 1:
        return ""

    from functools import lru_cache

    # Count valid ways from position (r,c) with current balance
    @lru_cache(maxsize=None)
    def count_from(r, c, balance):
        """Count valid 2D bracket configurations from cell (r,c) with given balance"""
        if r == n and c == m:
            return 1 if balance == 0 else 0

        ways = 0

        # Option 1: place '(' - balance increases by 1
        if balance + 1 <= n * 2:  # sanity check
            ways += count_from(r, c + 1, balance + 1) if c + 1 < m else 0

        # Option 2: place ')' - balance decreases by 1 (only if balance > 0)
        if balance > 0:
            ways += count_from(r + 1, c, balance - 1) if r + 1 < n else 0

        return ways

    # Sort cells by priority
    cells = []
    for i in range(n):
        for j in range(m):
            cells.append((priorities[i][j], i, j))
    cells.sort(key=lambda x: x[0])

    # Build the k-th correct bracket array
    grid = [[''] * m for _ in range(n)]

    for priority, r, c in cells:
        # Count valid completions if we place '(' here
        with_open = count_from(r, c + 1, 0) if c + 1 < m else 0

        if with_open < k:
            # Not enough ways with '(', must use ')'
